Solution A: function startGameOfLife(canvasId){const canvas=document.getElementById(canvasId);if(!canvas)return;const ctx=canvas.getContext('2d');const size=500;canvas.width=size;canvas.height=size;const cols=50;const rows=50;const cellSize=size/cols;let grid=Array.from({length:rows},()=>Array(cols).fill(0));let age=Array.from({length:rows},()=>Array(cols).fill(0));let dying=[];let speed=5;let lastStep=0;let animId=null;const emojis=['🟢','🌱','🌿','🌳','🌲','🍀','🌼'];function draw(){ctx.clearRect(0,0,size,size);for(let y=0;y<rows;y++){for(let x=0;x<cols;x++){if(grid[y][x]){const e=emojis[Math.min(age[y][x],emojis.length-1)];ctx.font=`${cellSize-2}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(e,x*cellSize+cellSize/2,y*cellSize+cellSize/2);} } } dying.forEach(d=>{ctx.globalAlpha=d.alpha;ctx.font=`${cellSize-2}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('💀',d.x*cellSize+cellSize/2,d.y*cellSize+cellSize/2);});ctx.globalAlpha=1; }function step(){let newGrid=Array.from({length:rows},()=>Array(cols).fill(0));let newAge=Array.from({length:rows},()=>Array(cols).fill(0));for(let y=0;y<rows;y++){for(let x=0;x<cols;x++){let count=0;for(let dy=-1;dy<=1;dy++){for(let dx=-1;dx<=1;dx++){if(dx===0&&dy===0)continue;const nx=(x+dx+cols)%cols;const ny=(y+dy+rows)%rows;if(grid[ny][nx])count++;}}if(grid[y][x]){if(count===2||count===3){newGrid[y][x]=1;newAge[y][x]=age[y][x]+1;}else{dying.push({x,y,alpha:1});}}else{if(count===3){newGrid[y][x]=1;newAge[y][x]=1;}}}}grid=newGrid;age=newAge;}function loop(timestamp){if(!lastStep)lastStep=timestamp;const delta=(timestamp-lastStep)/1000;if(delta>=1/speed){step();lastStep=timestamp;}dying.forEach(d=>d.alpha-=0.02);dying=ing.filter(d=>d.alpha>0);draw();animId=requestAnimationFrame(loop);}function toggleCell(e){const rect=canvas.getBoundingClientRect();const cx=e.clientX-rect.left;const cy=e.clientY-rect.top;const x=Math.floor(cx/cellSize);const y=Math.floor(cy/cellSize);grid[y][x]=grid[y][x]?0:1;age[y][x]=grid[y][x]?1:0;draw();}function randomize(){for(let y=0;y<rows;y++){for(let x=0;x<cols;x++){grid[y][x]=Math.random()<0.2?1:0;age[y][x]=grid[y][x]?1:0;}}draw();}function clear(){grid=Array.from({length:rows},()=>Array(cols).fill(0));age=Array.from({length:rows},()=>Array(cols).fill(0));dying=[];draw();}function placePattern(pattern){clear();const offsetX=Math.floor(cols/2);const offsetY=Math.floor(rows/2);pattern.forEach(([dx,dy])=>{const x=offsetX+dx;const y=offsetY+dy;if(x>=0&&x<cols&&y>=0&&y<rows){grid[y][x]=1;age[y][x]=1;}});draw();}const patterns={Glider:[[0,0],[1,0],[2,0],[2,1],[1,2]],Blinker:[[0,0],[1,0],[2,0]],GosperGun:[[-1,0],[-1,1],[0,0],[0,1],[0,2],[1,0],[1,2],[2,0],[2,1],[3,0],[3,1],[4,0],[4,-1],[5,-2],[5,-1],[6,-2],[6,-1],[5,2],[5,3],[6,2],[6,3],[7,1],[7,0],[8,1],[8,0],[9,0],[9,-1],[10,-1],[10,-2]],Pulsar:[[2,0],[3,0],[4,0],[8,0],[9,0],[10,0],[2,5],[3,5],[4,5],[8,5],[9,5],[10,5],[2,7],[3,7],[4,7],[8,7],[9,7],[10,7],[2,12],[3,12],[4,12],[8,12],[9,12],[10,12],[0,2],[0,3],[0,4],[0,8],[0,9],[0,10],[5,2],[5,3],[5,4],[5,8],[5,9],[510],[7,2],[7,3],[7,4],[7,8],[7,9],[7,10],[12,2],[12,3],[12,4],[12,8],[12,9],[12,10]]};const ui=document.createElement('div');ui.style.marginTop='10px';const select=document.createElement('select');['Glider','Blinker','Gosper Gun','Pulsar'].forEach(name=>{const opt=document.createElement('option');opt.value=name;opt.textContent=name;select.appendChild(opt);});select.addEventListener('change',()=>{placePattern(patterns[select.value.replace(' ','')]);});ui.appendChild(select);const speedLabel=document.createElement('label');speedLabel.textContent='Speed:';speedLabel.style.marginLeft='10px';const speedSlider=document.createElement('input');speedSlider.type='range';speedSlider.min='1';speedSlider.max='10';speedSlider.value='5';speedSlider.addEventListener('input',()=>{speed=parseInt(speedSlider.value);});ui.appendChild(speedLabel);ui.appendChild(speedSlider);const randBtn=document.createElement('button');randBtn.textContent='Randomize';randBtn.style.marginLeft='10px';randBtn.onclick=randomize;ui.appendChild(randBtn);const clearBtn=document.createElement('button');clearBtn.textContent='Clear';clearBtn.style.marginLeft='5px';clearBtn.onclick=clear;ui.appendChild(clearBtn);canvas.parentNode.insertBefore(ui,canvas.nextSibling);canvas.addEventListener('click',toggleCell);animId=requestAnimationFrame(loop);}

